import 'package:flutter/material.dart';
import 'dart:async';

void main() {
  runApp(LocationTracker());
}

class LocationTracker extends StatelessWidget {
  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      home: TrackingScreen(),
    );
  }
}

class TrackingScreen extends StatefulWidget {
  @override
  _TrackingScreenState createState() => _TrackingScreenScreenState();
}
